-- ============================================
-- 1. 黑神话：悟空 — 完整攻略 (已发售)
-- ============================================
UPDATE game_wiki SET
background = background || E'\n\n## 🎮 新手攻略\n\n### 开局建议\n1. **出身选择**：推荐\"灵猴\"出身，初始属性均衡，适合新手。\"石猴\"出身防御高但攻击低，适合喜欢稳妥打法的玩家。\n2. **前期加点**：优先加\"气力\"（影响闪避次数）和\"根骨\"（影响血量），前两章不要加\"灵性\"（法术伤害），收益太低。\n3. **第一章必拿**：击败灵虚子后不要急着走，回到寺庙废墟可以找到隐藏宝箱→**定风珠**（免疫黄风岭沙暴伤害，极其重要）。\n4. **金币用途**：优先升级葫芦（回血次数），其次买属性丹药，最后才是装备。',

worldview = worldview || E'\n\n## ⚔️ BOSS 攻略\n\n### 第一章 BOSS\n\n**灵虚子（道观）**\n- 难度：★★☆☆☆\n- 核心机制：三段剑气，第三段有红光预警\n- 打法：贴脸绕后，它转身很慢。定身术锁住后棍花最大化输出。不要远程放风筝——它的剑气比你的法术快。\n- 掉落：灵虚子魂魄 → 解锁\"灵虚变身\"\n\n**黑风大王（禅院）**\n- 难度：★★★☆☆\n- 核心机制：分身×3，只有一个是真身。真身的禅杖冒黑烟。\n- 打法：火眼金睛可识别真身。不要同时打三个分身——先找真身，定身→输出→闪避→循环。\n- 掉落：黑风禅杖（武器）\n\n### 第二章 BOSS\n\n**黄风怪（黄风岭）**\n- 难度：★★★★☆（没有定风珠则为★★★★★）\n- 核心机制：沙暴全屏AOE，每秒扣血\n- 打法：必须装备定风珠！沙暴来临时打开背包→使用定风珠→沙暴消失→全力输出。没有定风珠的话只能用无敌帧硬躲，容错率极低。\n- 掉落：黄风魂魄\n\n**虎先锋（卧虎寺）**\n- 难度：★★★★☆\n- 核心机制：三段连抓+扑杀。扑杀后必接咆哮（眩晕周围）\n- 打法：虎先锋的扑杀前摇极短。看到他后腿蹬地→立刻侧闪→不能后闪（扑杀距离覆盖后闪）。咆哮前有黄色气浪→跳起可规避眩晕。\n- 掉落：虎骨（锻造材料）\n\n### 第三章 BOSS\n\n**黄眉大王（小西天）**\n- 难度：★★★★★\n- 核心机制：人种袋——随机吸入一个道具/技能，被吸的道具此战无法使用\n- 打法：战前把废品道具填满背包——人种袋会优先吸废品。你的金箍棒不会被吸（剧情保护）。半血后黄眉变金身→用火系技能破金身→否则伤害减半。\n- 掉落：人种袋（法宝）\n\n**亢金龙（雷音寺）**\n- 难度：★★★★★\n- 核心机制：飞天+雷霆万钧。落地时产生雷电场\n- 打法：飞天时蓄力戳棍→落地瞬间释放→可打断雷霆万钧。雷电场用跳跃规避——滞空时不受雷电伤害。立棍打龙头伤害最高。\n\n### 第四章 BOSS\n\n**蜘蛛精（盘丝洞）**\n- 难度：★★★★☆\n- 核心机制：蛛网减速+小蜘蛛围攻+毒素叠加\n- 打法：优先清小蜘蛛（每只都会叠加毒素）。蛛网用火烧（火系技能可摧毁蛛网）。半血后蜘蛛精露出本体→近身拼刀→不要远程（她半血后远程伤害翻倍）。\n- 隐藏：如果第三章救下了\"猪八戒\"，此战它会帮你牵制小蜘蛛。\n\n### 第五章 BOSS\n\n**牛魔王（火焰山）**\n- 难度：★★★★★\n- 核心机制：霸体+冲锋+地震三连\n- 打法：牛魔王全程霸体——定身术无效！只能靠精准闪避。冲锋前会刨地两次→第二次刨完→立刻侧闪。地震三连的节奏是\"咚—咚—咚\"→每下间隔1.5秒→掌握节奏后在地震间隙偷刀。\n- 弱点：牛魔王转身极慢，绕后是唯一安全的输出时间。\n- 隐藏：如果之前没有杀铁扇公主，她会来劝架→战斗直接跳过（获得\"夫妻团圆\"成就）。\n\n**红孩儿（火焰山）**\n- 难度：★★★☆☆\n- 核心机制：三昧真火+风火轮\n- 打法：让八戒拉仇恨（切换角色），自己用远程蓄力戳棍。红孩儿被击中5次后会进CD→冲到面前→定身→一轮爆发。\n- 掉落：三昧真火（变身）',

developer_notes = developer_notes || E'\n\n## 💡 流派推荐\n\n### 1. 戳棍流（新手友好）\n- 核心：戳棍+定身术+高暴击\n- 加点：气力 > 灵性 > 根骨\n- 玩法：拉开距离→蓄力戳棍→定身→戳棍×3→闪避→循环\n- 优点：安全、简单、容错高\n- 缺点：打得慢、对霸体BOSS乏力\n\n### 2. 劈棍流（均衡）\n- 核心：劈棍+分身术+高攻击\n- 加点：灵性 = 气力 > 根骨\n- 玩法：近身→劈棍连段→分身吸引火力→继续劈→闪避\n- 优点：输出高、节奏爽快\n- 缺点：需要掌握精准闪避时机\n\n### 3. 立棍流（高手向）\n- 核心：立棍+变身切换+无敌帧\n- 加点：气力 > 灵性 > 根骨\n- 玩法：利用立棍的范围攻击清小怪→BOSS战切换戳棍\n- 优点：刷图效率极高\n- 缺点：对单体BOSS输出不足\n\n### 4. 法术流（娱乐向）\n- 核心：法术+法宝+变身循环\n- 加点：灵性 > 气力 > 根骨\n- 玩法：法术轰炸→变身→法宝→再法术\n- 优点：视觉华丽、群怪无敌\n- 缺点：法力消耗大、BOSS战乏力\n\n## 🔑 隐藏要素\n\n1. **真结局条件**：六根全部收集+第四章不杀蜘蛛精+第五章救铁扇公主→第六章解锁真结局\n2. **隐藏BOSS·二郎神**：第六章回到花果山→击碎山顶巨石→进入隐藏区域→BOSS战→胜利获得\"八九玄功\"\n3. **金箍棒最终形态**：收集全部72颗\"定海神珍\"（每章隐藏区域×12）→金箍棒进化为\"如意金箍棒·真\"→攻击力翻倍\n4. **筋斗云**：第三章在雷音寺塔顶找到破损的筋斗云→第五章火焰山修复→可在大地图自由飞行\n5. **DLC联动**：本体通关后→标题画面出现\"西天取经\"选项→8月DLC发售时自动解锁',

maps = maps || E'[{"name":"花果山","desc":"起始区域。曾经的人间仙境如今满目疮痍，玩家在此学习基础操作。隐藏：瀑布后可进入\"水帘洞\"——二周目专属区域"},{"name":"黄风岭","desc":"第二章场景。黄沙漫天的险峻山脉，黄风怪的老巢。关键道具\"定风珠\"在寺庙废墟隐藏宝箱中，拿到后沙暴不再扣血"},{"name":"小西天","desc":"第四章场景。冰雪覆盖的佛国废墟，暗藏惊天秘密。隐藏BOSS\"二郎神\"入口在此"},{"name":"火焰山","desc":"第五章场景。熔岩与焦土，牛魔王与铁扇公主的悲剧上演之地。可跳过牛魔王战斗获得\"夫妻团圆\"成就"},{"name":"盘丝洞","desc":"第三章场景。蜘蛛精的巢穴。隐藏区域中的\"猪八戒\"是可救NPC——救了会影响后续BOSS战"},{"name":"雷音寺","desc":"大型寺庙群。亢金龙BOSS战场地。塔顶有破损的筋斗云——为大地图自由飞行做铺垫"},{"name":"花果山·水帘洞","desc":"终章回归之地。天命人最终面对自己的真实身份。二周目新增真结局路线"}]'
WHERE game_id = (SELECT id FROM games WHERE title = '黑神话：悟空');

-- ============================================
-- 2. 燕云十六声 — 新手攻略 (已发售)
-- ============================================
UPDATE game_wiki SET
developer_notes = developer_notes || E'\n\n## 🎮 新手开荒攻略\n\n### 出身选择建议\n1. **将门出身**：初始武力高，适合战斗型玩家。开局送\"赵家枪法\"残卷。\n2. **商贾出身**：初始财力雄厚，经商收益+20%。适合想通过商业积累资源的玩家。\n3. **寒门出身**：各项属性均衡偏低，但经验获取+15%——成长最快。\n4. **道门出身**：初始内功高，适合法术流派。开局送\"太极拳\"入门。\n\n### 前期路线\n1. **1-10级**：在汴京城内做新手任务，学会基础战斗和生活技能。建议先学采集+挖矿。\n2. **10-20级**：出城探索汴京周边，开始接触帮派系统。建议加入一个大帮派——帮派任务经验极高。\n3. **20-30级**：前往幽州——这里怪物等级高但经验多，组队效率最高。\n4. **30级+**：开启\"燕云收复\"主线任务链，准备参与大型攻城战。\n\n### 帮派选择\n- **PVE玩家**：加入生活帮派，专注采集+制造+贸易\n- **PVP玩家**：加入战斗帮派，参与帮派战+领土争夺\n- **休闲玩家**：加入社交帮派，参与活动+副本\n\n### 赚钱方法\n1. 汴京→幽州跑商（单程利润30-50%）\n2. 采集高级材料在拍卖行出售\n3. 帮派任务（每日必做）\n4. 参与攻城战（胜方帮派有大量分红）\n\n### 战斗技巧\n- 长枪克制刀剑（距离优势）\n- 内功完克物理攻击（气劲减免）\n- 暗器无视防御（适合打高防BOSS）\n- 骑马作战伤害×1.5倍（但不灵活）',

background = background || E'\n\n## ⚔️ 副本攻略\n\n### 新手副本：汴京地牢（15级）\n- BOSS：狱卒统领\n- 机制：召唤2个小兵→半血后狂暴（攻速+50%）\n- 打法：先清小兵→攒气→BOSS狂暴时放必杀→一套带走\n- 掉落：制式长剑（蓝装）\n\n### 中级副本：华山剑冢（25级）\n- BOSS：剑灵\n- 机制：剑气×5（躲弹幕）+ 万剑归宗（全屏AOE）\n- 打法：弹幕阶段靠走位（别站桩！）→AOE读条时打断（弓蓄力爆头）→打断后全力输出\n- 掉落：华山剑谱（紫装）\n\n### 高级副本：雁门关战场（40级）\n- BOSS：契丹大将\n- 机制：骑马冲锋+弓箭齐射+召狼群\n- 打法：组队必须。T拉仇恨→治疗站高处→DPS先清狼群→再集火BOSS→注意躲避弓雨（地上有红圈提示）\n- 掉落：契丹战甲（橙装）\n\n### 终极副本：皇宫禁地（50级）\n- BOSS：？？？\n- 机制：多阶段变身+地形变化+时间限制30分钟\n- 打法：第一阶段站台子边缘→第二阶段集中火力打破皇帝金身→第三阶段躲避全屏AOE+所有人集火\n- 掉落：帝王武器系列（随机）\n\n## 💡 流派推荐\n1. **赵家枪法流**（均衡/新手推荐）：长枪+中距离输出，安全高效\n2. **太极拳流**（高手向）：徒手格斗+高内功，反制一切物理攻击\n3. **暗杀流**（PVP倾向）：暗器+潜行，适合野外PK和偷袭\n4. **骑马流**（团战专用）：马上作战伤害高，攻城战必备\n5. **治疗流**（团队必备）：内功心法+治疗技能，副本抢着要'
WHERE game_id = (SELECT id FROM games WHERE title = '燕云十六声');

-- ============================================
-- 3. 影之刃零 — Demo试玩攻略 (未发售，有足够信息)
-- ============================================
UPDATE game_wiki SET
developer_notes = developer_notes || E'\n\n## 🎮 Demo 试玩攻略（基于公开实机演示）\n\n### 战斗系统速成\n1. **核心循环**：轻攻击→积攒连击数→重攻击处决→闪避取消后摇→轻攻击\n2. **拼刀机制**：敌人攻击瞬间→按格挡→完美拼刀→敌人硬直→处决\n3. **魂术系统**：L1+R1同时按→消耗\"灵魂条\"（蓝条下方黄色条）→进入\"魂术爆发\"状态→攻击力×2，持续15秒→每次使用后\"剩余寿命\"-1天\n4. **武器切换**：战斗中按方向键切换武器→不同武器有独立的连击树→切换时有无敌帧→可用于取消硬直\n\n### Demo BOSS 攻略\n\n**机关统领（Demo开场BOSS）**\n- 难度：★★☆☆☆（教学性质）\n- 机制：蒸汽锤砸地（直线冲击波）+ 齿轮飞镖（跟踪）\n- 打法：这是一场教学战→跟着提示操作→格挡锤击→闪避飞镖→近身轻攻击连段→重攻击处决\n\n**黑衣刺客（Demo中期BOSS）**\n- 难度：★★★★☆\n- 机制：瞬移+飞镖连射+背刺+烟雾弹\n- 打法：不要追她→等她瞬移结束→她会出现在你背后→提前转身→格挡背刺→反击。烟雾弹期间用飞镰钩取她出来。\n\n**魂之镜像（Demo最终BOSS？）**\n- 难度：★★★★★\n- 机制：复制你的武器和技能→比你多50%血量\n- 打法：这是你自己——你会的他都会。唯一的优势：他不会切换武器！利用武器切换的无敌帧，在三种武器形态间切换→他只能模仿当前武器→切换后立刻输出。\n\n### 流派方向（基于已知技能树）\n1. **血影剑流**：高攻速+高暴击+赌命。搭配\"魂术爆发\"→15秒内毁天灭地→但每次用都减寿命\n2. **玄铁重剑流**：霸体+高伤害+慢攻速。适合稳重玩家——吃我一剑就够\n3. **机关弩流**：远程风筝+炸弹控场。适合不擅长近战的玩家\n4. **魂之手特化**：不依赖武器→专门强化左臂义肢→大范围AOE→但每次攻击扣寿命',

maps = maps || E'[{"name":"雨城","desc":"Demo展示区域。常年被灵魂雨笼罩的阴暗都市。垂直结构复杂，学会用飞镰钩索上下移动是关键"},{"name":"机关城","desc":"预告中展示的西域总部。蒸汽朋克风格的机械堡垒，充满陷阱和机关"},{"name":"残剑峰","desc":"传统武侠区域。在实机演示中以远景出现，预计有大量传统武术招式可学习"}]'
WHERE game_id = (SELECT id FROM games WHERE title = '影之刃零');

